def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0

    # Using the explicit formula:
    # A(n, m) = sum_{k=0}^{m+1} (-1)^k * comb(n+1, k) * (m+1-k)^n

    from math import comb

    result = 0
    for k in range(m + 2):
        term = comb(n + 1, k) * ((m + 1 - k) ** n)
        if k % 2 == 1:
            result -= term
        else:
            result += term
    return result
