def get_maxgold(mine, n, m):
    if n == 0 or m == 0:
        return 0

    # dp[i][j] stores the maximum gold collected reaching cell (i, j)
    # We only care about the first column as starting points
    dp = [[0 for _ in range(m)] for _ in range(n)]

    for i in range(n):
        dp[i][0] = mine[i][0]

    for j in range(1, m):
        for i in range(n):
            # Possible moves to reach (i, j) are from (i-1, j-1), (i, j-1), (i+1, j-1)
            prev_max = dp[i][j-1]
            if i > 0:
                prev_max = max(prev_max, dp[i-1][j-1])
            if i < n - 1:
                prev_max = max(prev_max, dp[i+1][j-1])

            dp[i][j] = mine[i][j] + prev_max

    # The answer is the maximum value in the last column
    max_gold = 0
    for i in range(n):
        max_gold = max(max_gold, dp[i][m-1])

    return max_gold
