import math

def first_Factorial_Divisible_Number(x):
    if x == 1:
        return 1

    def get_prime_factors(n):
        factors = {}
        d = 2
        temp = n
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    def count_p_in_factorial(n, p):
        count = 0
        while n > 0:
            n //= p
            count += n
        return count

    prime_factors = get_prime_factors(x)

    # The answer must be at least the largest prime factor of x
    # We can use binary search or a simple incrementing search.
    # Since we need the smallest n such that for all p^k in x, count_p_in_factorial(n, p) >= k

    low = 1
    high = x # n! is always divisible by x for n=x (except x=1)
    ans = x

    while low <= high:
        mid = (low + high) // 2
        possible = True
        for p, k in prime_factors.items():
            if count_p_in_factorial(mid, p) < k:
                possible = False
                break

        if possible:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
```

