import math

class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        def count_multiples(target, coins):
            n = len(coins)
            count = 0
            # Inclusion-Exclusion Principle using bitmask
            # Since len(coins) <= 15, 2^15 is 32768, which is efficient.
            for i in range(1, 1 << n):
                lcm_val = 1
                bits_set = 0
                for j in range(n):
                    if (i >> j) & 1:
                        lcm_val = (lcm_val * coins[j]) // math.gcd(lcm_val, coins[j])
                        bits_set += 1
                        # Optimization: if lcm exceeds target, no need to continue
                        if lcm_val > target:
                            break

                if lcm_val <= target:
                    if bits_set % 2 == 1:
                        count += target // lcm_val
                    else:
                        count -= target // lcm_val
            return count

        # Binary search for the k-th smallest amount
        # Lower bound is the minimum coin, upper bound is min(coins) * k
        low = 1
        high = min(coins) * k
        ans = high

        while low <= high:
            mid = (low + high) // 2
            if count_multiples(mid, coins) >= k:
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans

