            while queue:
                x, y = queue.popleft()
                for dx, dy in [(1, 2), (1, -2), (-1, 2), (-1, -2), (2, 1), (2, -1), (-2, 1), (-2, -1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and dist[nx][ny] == -1:
                        dist[nx][ny] = dist[x][y] + 1
                        queue.append((nx, ny))
            return dist

        # Precompute distances between all points of interest
        # Points of interest: knight's start and all pawn positions
        all_points = [(kx, ky)] + positions
        num_points = len(all_points)
        adj = [[0] * num_points for _ in range(num_points)]

        for i in range(num_points):
            px, py = all_points[i]
            dists = get_dist(px, py)
            for j in range(num_points):
