class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0

        # Using a sliding window approach to find the number of valid substrings.
        # For each starting position 'left', we find the furthest 'right' such that
        # the substring s[left:right+1] satisfies the k-constraint.
        # However, since the constraints are small (n <= 50), a simple O(n^2) 
        # approach is perfectly efficient.

        for left in range(n):
            zeros = 0
            ones = 0
            for right in range(left, n):
                if s[right] == '0':
                    zeros += 1
                else:
                    ones += 1

                if zeros <= k or ones <= k:
                    count += 1
                else:
                    # If the current substring doesn't satisfy the constraint,
                    # any larger substring starting at 'left' won't either.
                    break

        return count

