class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # dp[i][j] is the maximum length of a good subsequence 
        # ending at index i with exactly j transitions (seq[p] != seq[p+1]).
        # Since k is small (up to 25) and n is up to 500, O(n^2 * k) is acceptable.
        dp = [[0] * (k + 1) for _ in range(n)]

        for i in range(n):
            # Base case: a subsequence of length 1 has 0 transitions.
            dp[i][0] = 1
            for j in range(i):
                if nums[i] == nums[j]:
                    # No transition added
                    for diff in range(k + 1):
                        if dp[j][diff] > 0:
                            dp[i][diff] = max(dp[i][diff], dp[j][diff] + 1)
                else:
                    # One transition added
                    for diff in range(k):
                        if dp[j][diff] > 0:
                            dp[i][diff + 1] = max(dp[i][diff + 1], dp[j][diff] + 1)

        ans = 0
        for i in range(n):
            for j in range(k + 1):
                ans = max(ans, dp[i][j])
        return ans

