    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        n = len(s)
        min_len = float('inf')
        candidates = []

        # Iterate through all possible substrings
        for i in range(n):
            count_ones = 0
            for j in range(i, n):
                if s[j] == '1':
                    count_ones += 1

                # If we found a beautiful substring (exactly k ones)
                if count_ones == k:
                    current_len = j - i + 1
                    substring = s[i:j+1]

                    if current_len < min_len:
                        min_len = current_len
                        candidates = [substring]
                    elif current_len == min_len:
                        candidates.append(substring)

                    # Since we want the shortest, and adding more characters 
                    # will only increase length, we break the inner loop
                    break

                # If we exceed k ones, no need to continue this starting index
                if count_ones > k:
                    break

        if not candidates:
            return ""

        # Return the lexicographically smallest among the shortest
        candidates.sort()
