from typing import List

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # The problem is essentially finding the shortest path between characters in a graph.
        # Since there are only 26 lowercase English letters, we can use the Floyd-Warshall algorithm.

        inf = float('inf')
        # dist[i][j] will store the minimum cost to change character i to character j
        dist = [[inf] * 26 for _ in range(26)]

        # Distance to self is 0
        for i in range(26):
            dist[i][i] = 0

        # Initialize distances with given costs
        for o, c, w in zip(original, changed, cost):
            u = ord(o) - ord('a')
            v = ord(c) - ord('a')
            if w < dist[u][v]:
                dist[u][v] = w

        # Floyd-Warshall algorithm to find all-pairs shortest paths
        for k in range(26):
            for i in range(26):
                if dist[i][k] == inf:
                    continue
                for j in range(26):
                    if dist[k][j] != inf:
                        if dist[i][j] > dist[i][k] + dist[k][j]:
                            dist[i][j] = dist[i][k] + dist[k][j]

        total_cost = 0
        for s_char, t_char in zip(source, target):
            if s_char == t_char:
                continue

            u = ord(s_char) - ord('a')
            v = ord(t_char) - ord('a')

            if dist[u][v] == inf:
                return -1

            total_cost += dist[u][v]

        return total_cost

