        # Find all starting indices of substring 'b'
        indices_b = []
        for j in range(n - len_b + 1):
            if s[j : j + len_b] == b:
                indices_b.append(j)

        if not indices_b:
            return []

        result = []
        # For each index i in indices_a, check if there exists j in indices_b
        # such that |i - j| <= k, which is equivalent to i - k <= j <= i + k
        for i in indices_a:
            # Use binary search to find if any j exists in the range [i - k, i + k]
