        idx += 1
        counts = {}
        for _ in range(K):
            val = int(input_data[idx])
            idx += 1
            counts[val] = counts.get(val, 0) + 1
        dice_counts.append((K, counts))

    # We want to maximize P(X=Y) = sum_{v} P(X=v) * P(Y=v)
    # P(X=v) = count_X(v) / K_X
    # P(Y=v) = count_Y(v) / K_Y
    # P(X=Y) = (1 / (K_X * K_Y)) * sum_{v} (count_X(v) * count_Y(v))

