    # Total complexity O(N^2 * unique_values_per_die) is too slow if we aren't careful,
    # but the sum of K_i is 10^5.
    # The number of pairs is N(N-1)/2.
    # For each pair (i, j), we calculate sum_{v in intersection} count_i(v) * count_j(v).

    max_prob = 0.0

    # To optimize, we can iterate through the smaller dictionary of the two dice.
    for i in range(N):
        K_i, counts_i = dice_counts[i]
