class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        # Segment tree to store the maximum capacity in a range of baskets
        tree = [0] * (4 * n)

        def build(node, start, end):
            if start == end:
                tree[node] = baskets[start]
                return
            mid = (start + end) // 2
            build(2 * node, start, mid)
            build(2 * node + 1, mid + 1, end)
            tree[node] = max(tree[2 * node], tree[2 * node + 1])

        def update(node, start, end, idx, val):
            if start == end:
                tree[node] = val
                return
            mid = (start + end) // 2
            if idx <= mid:
                update(2 * node, start, mid, idx, val)
            else:
                update(2 * node + 1, mid + 1, end, idx, val)
            tree[node] = max(tree[2 * node], tree[2 * node + 1])

        def query(node, start, end, val):
            # Find the leftmost index i such that baskets[i] >= val
            if tree[node] < val:
                return -1
            if start == end:
                return start

            mid = (start + end) // 2
            # Try the left child first to find the leftmost available basket
            res = query(2 * node, start, mid, val)
            if res == -1:
                res = query(2 * node + 1, mid + 1, end, val)
            return res

        build(1, 0, n - 1)

        unplaced_count = 0
        for fruit in fruits:
            idx = query(1, 0, n - 1, fruit)
            if idx != -1:
                # Mark basket as used by setting its capacity to 0
                update(1, 0, n - 1, idx, 0)
            else:
                unplaced_count += 1

        return unplaced_count

