    def get_rotations(poly):
        # A polyomino is a list of (r, c) tuples.
        # Rotations: (r, c) -> (c, -r) -> (-r, -c) -> (-c, r)
        rots = []
        curr = poly
        for _ in range(4):
            # Normalize: shift so min_r=0, min_c=0
            min_r = min(p[0] for p in curr)
            min_c = min(p[1] for p in curr)
            normalized = sorted([(p[0] - min_r, p[1] - min_c) for p in curr])
            if normalized not in rots:
                rots.append(normalized)
            # Rotate 90 degrees clockwise
            curr = [(p[1], -p[0]) for p in curr]
        return rots

    all_rotations = [get_rotations(p) for p in polyominoes_raw]

    # Pre-calculate all possible placements for each polyomino
    # A placement is a set of (r, c) coordinates in the 4x4 grid
    placements = []
