import collections

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        # Using Breadth-First Search (BFS) to find the shortest path
        # The state is the current value of x.
        # Since x can increase, we need a reasonable upper bound.
        # Given x, y <= 10^4, a bound of 11000 is safe.
        queue = collections.deque([(x, 0)])
        visited = {x}
        limit = 11000

        while queue:
            curr, dist = queue.popleft()

            if curr == y:
                return dist

            # Possible next moves
            next_moves = []

            # 1. Divide by 11
            if curr % 11 == 0:
                next_moves.append(curr // 11)

            # 2. Divide by 5
            if curr % 5 == 0:
                next_moves.append(curr // 5)

            # 3. Decrement
            if curr > 0:
                next_moves.append(curr - 1)

            # 4. Increment
            if curr < limit:
                next_moves.append(curr + 1)

            for move in next_moves:
                if move not in visited:
                    # Optimization: if we reach y via increment/decrement, 
                    # we can calculate the distance immediately.
                    # However, standard BFS handles this.
                    visited.add(move)
                    queue.append((move, dist + 1))

        return -1
