class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        if n <= 1:
            return 0

        # dp[i][char_idx] is the minimum operations for the prefix of length i+1,
        # where the i-th character is replaced by char_idx (0-25).
        # We use a large value for infinity.
        INF = float('inf')
        dp = [[INF] * 26 for _ in range(n)]

        def is_almost_equal(c1_idx, c2_idx):
            return abs(c1_idx - c2_idx) <= 1

        # Base case: first character
        for c in range(26):
            # Cost is 1 if we change the character, 0 if we keep it
            dp[0][c] = 1 if ord(word[0]) - ord('a') != c else 0

        for i in range(1, n):
            current_char_orig_idx = ord(word[i]) - ord('a')
            for curr_c in range(26):
                cost = 1 if current_char_orig_idx != curr_c else 0

                # Find the minimum dp[i-1][prev_c] such that prev_c and curr_c are not almost-equal
                min_prev = INF
                for prev_c in range(26):
                    if not is_almost_equal(prev_c, curr_c):
                        if dp[i-1][prev_c] < min_prev:
                            min_prev = dp[i-1][prev_c]

                if min_prev != INF:
                    dp[i][curr_c] = min_prev + cost

        ans = min(dp[n-1])
        return ans

