class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Diagonals are identified by (r - c)
        # Bottom-left triangle (including middle diagonal): r - c >= 0
        # Top-right triangle: r - c < 0

        # Group elements by their diagonal ID (r - c)
