class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        if not grid or not grid[0]:
            return []

        rows = len(grid)
        cols = len(grid[0])
        result = []

        # We need to keep track of the global index of the cell in the zigzag path
        # to determine if it's an even or odd step (to skip every alternate cell).
        # However, the problem says "skip every alternate cell during the traversal".
        # This implies we follow the zigzag path and pick the 1st, 3rd, 5th... elements.

        zigzag_path = []
        for r in range(rows):
            if r % 2 == 0:
                # Traverse right
                for c in range(cols):
                    zigzag_path.append(grid[r][c])
            else:
                # Traverse left
                for c in range(cols - 1, -1, -1):
                    zigzag_path.append(grid[r][c])

        # The problem asks to skip every alternate cell.
        # Starting at (0,0) is the 1st cell (index 0).
        # We take index 0, skip index 1, take index 2, skip index 3...
        for i in range(0, len(zigzag_path), 2):
            result.append(zigzag_path[i])

